insert into change_headers (id, ts) values (72, '2026-11-07') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (72, 'ru', 'Теперь через диалог «Нашли ошибку?» можно сообщить не только об опечатке, но и об ошибке в расчётах. Выделите неверное число и нажмите Ctrl+Enter — в диалоге включится переключатель «Это ошибка в расчетах». Укажите, какое значение показывает игра (если знаете), и отправьте сообщение: к нему автоматически приложатся данные, нужные, чтобы воспроизвести расчёт, — открытая вкладка, ячейка, из которой взято число, и поля, значения которых отличаются от значений по умолчанию. Список приложенного можно посмотреть в диалоге перед отправкой; ресурсы в наличии не передаются. Скриншоты можно прислать в наш Discord.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'en', 'The “Found an error?” dialog now lets you report not only a typo but also a calculation error. Select the wrong number and press Ctrl+Enter — the “This is a calculation error” switch will be on in the dialog. Enter the value the game shows (if you know it) and send the message: the data needed to reproduce the calculation is attached automatically — the open tab, the cell the number was taken from, and the fields whose values differ from the defaults. You can review the attached list in the dialog before sending; the resources available are not sent. Screenshots can be sent to our Discord.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'pt', 'Agora, através da janela «Encontraste algum erro?», podes comunicar não só um erro ortográfico, mas também um erro de cálculo. Seleciona o número errado e prime Ctrl+Enter — na janela será ativado o interruptor «Isto é um erro de cálculo». Indica o valor que o jogo mostra (se o souberes) e envia a mensagem: serão anexados automaticamente os dados necessários para reproduzir o cálculo — o separador aberto, a célula de onde foi tirado o número e os campos cujos valores diferem dos predefinidos. Podes ver a lista do que é anexado na janela antes de enviar; os recursos disponíveis não são enviados. As capturas de ecrã podem ser enviadas para o nosso Discord.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'de', 'Über den Dialog „Hast du einen Fehler gefunden?“ kannst du jetzt nicht nur Tippfehler, sondern auch Rechenfehler melden. Markiere die falsche Zahl und drücke Strg+Enter – im Dialog ist dann der Schalter „Dies ist ein Rechenfehler“ eingeschaltet. Gib an, welchen Wert das Spiel anzeigt (falls bekannt), und sende die Nachricht ab: Die Daten, die zum Nachvollziehen der Berechnung nötig sind, werden automatisch angehängt – der geöffnete Tab, die Zelle, aus der die Zahl stammt, und die Felder, deren Werte von den Standardwerten abweichen. Die Liste der angehängten Daten kannst du vor dem Absenden im Dialog ansehen; die vorhandenen Rohstoffe werden nicht übermittelt. Screenshots kannst du in unserem Discord schicken.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'pl', 'Teraz przez okno „Znalazłem błąd?” można zgłosić nie tylko literówkę, ale także błąd w obliczeniach. Zaznacz nieprawidłową liczbę i naciśnij Ctrl+Enter — w oknie włączy się przełącznik „To błąd w obliczeniach”. Podaj wartość, którą pokazuje gra (jeśli ją znasz), i wyślij wiadomość: automatycznie zostaną do niej dołączone dane potrzebne do odtworzenia obliczeń — otwarta zakładka, komórka, z której pochodzi liczba, oraz pola, których wartości różnią się od domyślnych. Listę dołączonych danych można przejrzeć w oknie przed wysłaniem; dostępne surowce nie są przesyłane. Zrzuty ekranu można przesłać na nasz Discord.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'es', 'Ahora, desde el diálogo «¿Has encontrado algún error?», puedes informar no solo de una errata, sino también de un error de cálculo. Selecciona el número incorrecto y pulsa Ctrl+Enter: en el diálogo se activará el interruptor «Es un error de cálculo». Indica qué valor muestra el juego (si lo sabes) y envía el mensaje: se adjuntarán automáticamente los datos necesarios para reproducir el cálculo — la pestaña abierta, la celda de la que se tomó el número y los campos cuyos valores difieren de los predeterminados. Puedes revisar la lista de lo adjuntado en el diálogo antes de enviarlo; los recursos disponibles no se envían. Las capturas de pantalla puedes enviarlas a nuestro Discord.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'fr', 'La fenêtre de signalement d''erreur permet désormais de signaler non seulement une faute de frappe, mais aussi une erreur de calcul. Sélectionnez le nombre erroné et appuyez sur Ctrl+Enter : l''interrupteur « C''est une erreur de calcul » sera activé dans la fenêtre. Indiquez la valeur affichée par le jeu (si vous la connaissez) et envoyez le message : les données nécessaires pour reproduire le calcul y seront jointes automatiquement — l''onglet ouvert, la cellule d''où provient le nombre et les champs dont les valeurs diffèrent des valeurs par défaut. Vous pouvez consulter la liste des éléments joints dans la fenêtre avant l''envoi ; les ressources disponibles ne sont pas transmises. Les captures d''écran peuvent être envoyées sur notre Discord.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'it', 'Ora, tramite la finestra «Trovato un errore?», puoi segnalare non solo un refuso, ma anche un errore di calcolo. Seleziona il numero sbagliato e premi Ctrl+Enter: nella finestra si attiverà l''interruttore «È un errore di calcolo». Indica il valore mostrato dal gioco (se lo conosci) e invia il messaggio: verranno allegati automaticamente i dati necessari per riprodurre il calcolo — la scheda aperta, la cella da cui è stato preso il numero e i campi i cui valori differiscono da quelli predefiniti. Puoi consultare l''elenco dei dati allegati nella finestra prima dell''invio; le risorse disponibili non vengono inviate. Gli screenshot possono essere inviati sul nostro Discord.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'nl', 'Via het venster “Een taalfoutje gevonden?” kun je nu niet alleen een tikfout melden, maar ook een rekenfout. Selecteer het onjuiste getal en druk op Ctrl+Enter — in het venster wordt de schakelaar “Dit is een rekenfout” ingeschakeld. Geef aan welke waarde het spel toont (als je die weet) en verstuur het bericht: de gegevens die nodig zijn om de berekening na te bootsen, worden automatisch bijgevoegd — het geopende tabblad, de cel waaruit het getal komt en de velden waarvan de waarden afwijken van de standaardwaarden. De lijst met bijgevoegde gegevens kun je vóór het verzenden in het venster bekijken; de beschikbare grondstoffen worden niet meegestuurd. Screenshots kun je naar onze Discord sturen.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'sk', 'Cez dialóg „Našli ste chybu?“ teraz môžete nahlásiť nielen preklep, ale aj chybu vo výpočte. Označte nesprávne číslo a stlačte Ctrl+Enter — v dialógu sa zapne prepínač „Toto je chyba vo výpočte“. Uveďte, akú hodnotu ukazuje hra (ak ju poznáte), a odošlite správu: automaticky sa k nej priložia údaje potrebné na zopakovanie výpočtu — otvorená karta, bunka, z ktorej je číslo, a polia, ktorých hodnoty sa líšia od predvolených. Zoznam priložených údajov si môžete pred odoslaním pozrieť v dialógu; dostupné suroviny sa neodosielajú. Snímky obrazovky môžete poslať na náš Discord.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'tr', 'Artık “Hata mı buldunuz?” penceresinden yalnızca yazım hatalarını değil, hesaplama hatalarını da bildirebilirsiniz. Yanlış sayıyı seçip Ctrl+Enter tuşlarına basın — pencerede “Bu bir hesaplama hatası” anahtarı açık olacaktır. Oyunun gösterdiği değeri (biliyorsanız) girin ve mesajı gönderin: hesaplamayı yeniden yapmak için gereken veriler otomatik olarak eklenir — açık sekme, sayının alındığı hücre ve değerleri varsayılandan farklı olan alanlar. Eklenenlerin listesini göndermeden önce pencerede görebilirsiniz; mevcut kaynaklar gönderilmez. Ekran görüntülerini Discord sunucumuza gönderebilirsiniz.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (72, 'bs', 'Sada preko dijaloga „Našli ste grešku?“ možete prijaviti ne samo tipfeler, nego i grešku u izračunu. Označite pogrešan broj i pritisnite Ctrl+Enter — u dijalogu će se uključiti prekidač „Ovo je greška u izračunu“. Navedite koju vrijednost prikazuje igra (ako je znate) i pošaljite poruku: automatski će joj biti priloženi podaci potrebni da se izračun ponovi — otvorena kartica, ćelija iz koje je uzet broj i polja čije se vrijednosti razlikuju od zadanih. Spisak priloženog možete pogledati u dijalogu prije slanja; raspoloživi resursi se ne šalju. Snimke ekrana možete poslati na naš Discord.') on duplicate key update description = values(description);
